ebsite: Registration not approved for %s'=>'ההרשמה לא אושרה: %s','Hello {display_name},<br><br>Thank you for your interest. We could not approve your registration.<br><br>If you think this is a mistake, please contact us.'=>'שלום {display_name},<br><br>תודה על ההתעניינות. לא יכולנו לאשר את ההרשמה שלך.<br><br>אם נראה לך שזו טעות, אפשר לפנות אלינו.','Customer Type'=>'סוג לקוח','Region'=>'אזור','Country'=>'מדינה','Pending User'=>'משתמש ממתין','Approved User'=>'משתמש מאושר','Rejected User'=>'משתמש שנדחה','Unconfirmed User'=>'משתמש לא מאומת','ID'=>'מזהה','Date Registered'=>'תאריך הרשמה','Registration Details'=>'פרטי ההרשמה']];